/**
 * QR image-import regression tests (Iteration 4B, v0.3.2).
 *
 * These decode REAL PNG files (src/test/fixtures/qr, generated by
 * scripts/generate-qr-fixtures.py) through the same rgbaToGrey →
 * decodeWithCascade path that imageSource.ts runs after drawing an imported
 * image on a canvas. Only the canvas step itself is replaced (jsdom has no
 * canvas): src/test/png.ts supplies the RGBA pixels instead.
 *
 * Host-only evidence: these run in Node/jsdom with the real ZXing decoder.
 * They do not prove behaviour in iPhone Safari, and the fixtures are sanitized
 * stand-ins, not the customer screenshots that reported the regression.
 */
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { readPng } from '../../test/node/png.ts'
import { decodeBitmap, rgbaToGrey, type DecodeOptions, type DecodeResult } from './decode.ts'
import { decodeWithCascade, IMAGE_CASCADE, isWeakRead, type CascadeStep } from './decodeCascade.ts'
import type { GreyBitmap } from './rasterize.ts'
import { verifyRoundTrip } from './verify.ts'

// import.meta.dirname, not import.meta.url: under jsdom the module URL is not a file: URL.
const FIXTURES = join(import.meta.dirname, '../../test/fixtures/qr/')
const manifest = JSON.parse(readFileSync(`${FIXTURES}manifest.json`, 'utf-8')) as Record<string, { value: string; note: string }>
const noPause = { pause: async () => undefined }

function load(name: string): GreyBitmap {
  const image = readPng(`${FIXTURES}${name}`)
  return rgbaToGrey(image.data, image.width, image.height)
}

/** Fixtures that ZXing cannot read at native resolution (the regression class). */
const NATIVE_FAILURES = ['screenshot-upscaled-smooth.png', 'screenshot-upscaled-smooth-large.png', 'photo-noisy-card.png']

describe('QR image import with real image files', () => {
  it('has the expected fixture set', () => {
    expect(Object.keys(manifest).length).toBeGreaterThanOrEqual(12)
    for (const name of NATIVE_FAILURES) expect(manifest).toHaveProperty(name)
  })

  it.each(Object.keys(manifest))('%s decodes to the exact value and passes the redraw check', async (name) => {
    const expected = manifest[name]!.value
    const outcome = await decodeWithCascade(load(name), noPause)
    expect(outcome.result).toEqual({ status: 'decoded', format: 'qrcode', value: expected })
    expect(outcome.timedOut).toBe(false)
    expect(verifyRoundTrip('qrcode', expected)).toEqual({ ok: true })
  })

  it('preserves leading/trailing spaces, leading zeros and case exactly', async () => {
    const outcome = await decodeWithCascade(load('screenshot-exact-whitespace.png'), noPause)
    expect(outcome.result).toEqual({ status: 'decoded', format: 'qrcode', value: '  0000123  case-Sensitive  ' })
  })

  it('reads clean screenshots and custom artwork on the original image, first attempt', async () => {
    for (const name of ['screenshot-app-card.png', 'screenshot-logo-artwork.png', 'screenshot-dots-artwork.png', 'screenshot-rounded-artwork.png', 'transparent-background.png']) {
      const outcome = await decodeWithCascade(load(name), noPause)
      expect({ name, step: outcome.step, attempts: outcome.attempts }).toEqual({ name, step: 'original', attempts: 1 })
    }
  })

  it.each(NATIVE_FAILURES)('%s: fails at native resolution, then the QR sweep reads it before any all-format fallback', async (name) => {
    const base = load(name)
    // The regression: the unmodified image does not decode, even QR-only.
    expect(decodeBitmap(base, { tryHarder: true }).status).toBe('not-found')
    expect(decodeBitmap(base, { formats: ['qrcode'], tryHarder: true }).status).toBe('not-found')
    const outcome = await decodeWithCascade(base, noPause)
    expect(outcome.result).toEqual({ status: 'decoded', format: 'qrcode', value: manifest[name]!.value })
    expect(outcome.step).toMatch(/^qr-/)
    const sweepEnd = IMAGE_CASCADE.findIndex((step, index) => index > 0 && !step.formats)
    expect(outcome.attempts).toBeLessThanOrEqual(sweepEnd)
  })
})

describe('cascade ordering and view safety', () => {
  it('attempts the unmodified original image first, with every format', async () => {
    const base = load('screenshot-upscaled-smooth.png')
    const calls: Array<{ view: GreyBitmap; options: DecodeOptions | undefined }> = []
    const recordingDecode = (view: GreyBitmap, options?: DecodeOptions): DecodeResult => {
      calls.push({ view, options })
      return decodeBitmap(view, options)
    }
    await decodeWithCascade(base, { ...noPause, decode: recordingDecode })
    expect(calls[0]!.view).toBe(base)
    expect(calls[0]!.options?.formats).toBeUndefined()
    expect(calls.length).toBeGreaterThan(1)
  })

  it('places the QR sweep directly after the original and before all-format fallbacks', () => {
    const labels = IMAGE_CASCADE.map((step) => step.label)
    expect(labels[0]).toBe('original')
    const firstFallback = IMAGE_CASCADE.findIndex((step, index) => index > 0 && !step.formats)
    const sweep = IMAGE_CASCADE.slice(1, firstFallback)
    expect(sweep.length).toBeGreaterThanOrEqual(5)
    for (const step of sweep) expect(step.formats).toEqual(['qrcode'])
    expect(IMAGE_CASCADE.slice(firstFallback).every((step) => !step.formats)).toBe(true)
  })

  it('never crops: every view keeps the whole image (finder patterns and quiet zone intact)', () => {
    const base = load('screenshot-app-card.png')
    const before = base.data.slice()
    const ratio = base.width / base.height
    for (const step of IMAGE_CASCADE) {
      const view = step.view(base)
      if (!view) continue
      const viewRatio = view.width / view.height
      const rotated = Math.abs(1 / viewRatio - ratio) < Math.abs(viewRatio - ratio)
      // Integer box downscales floor each side, so allow ~1 % drift.
      expect({ step: step.label, close: Math.abs((rotated ? 1 / viewRatio : viewRatio) - ratio) / ratio < 0.01 }).toEqual({ step: step.label, close: true })
    }
    expect(base.data).toEqual(before)
  })
})

describe('weak reads do not pre-empt a QR code', () => {
  const qr: DecodeResult = { status: 'decoded', format: 'qrcode', value: 'MEMBER 0001' }
  const weak: DecodeResult = { status: 'unsupported', formatLabel: 'Codabar', value: 'A123B' }
  const steps: CascadeStep[] = [
    { label: 'original', view: (b) => b },
    { label: 'qr-a', formats: ['qrcode'], view: (b) => b },
    { label: 'qr-b', formats: ['qrcode'], view: (b) => b },
    { label: 'full', view: (b) => b },
  ]
  const base: GreyBitmap = { width: 10, height: 10, data: new Uint8ClampedArray(100).fill(255) }

  it('classifies detect-only and Code 39 reads as weak, checked formats as strong', () => {
    expect(isWeakRead(weak)).toBe(true)
    expect(isWeakRead({ status: 'decoded', format: 'code39', value: 'ABC' })).toBe(true)
    expect(isWeakRead(qr)).toBe(false)
    expect(isWeakRead({ status: 'decoded', format: 'code128', value: 'ABC' })).toBe(false)
  })

  it('keeps sweeping after a weak read and prefers the QR code', async () => {
    const results = [weak, { status: 'not-found' } as DecodeResult, qr]
    let call = 0
    const outcome = await decodeWithCascade(base, { ...noPause, steps, decode: () => results[call++]! })
    expect(outcome).toMatchObject({ result: qr, step: 'qr-b', attempts: 3 })
  })

  it('returns the first weak read unchanged when nothing better is found, skipping costly steps', async () => {
    const seen: string[] = []
    const outcome = await decodeWithCascade(base, {
      ...noPause,
      steps,
      decode: (_view, options) => {
        seen.push(options?.formats ? 'sweep' : 'full')
        return seen.length === 1 ? weak : { status: 'not-found' }
      },
    })
    expect(outcome).toMatchObject({ result: weak, step: 'original', attempts: 3, timedOut: false })
    expect(seen).toEqual(['full', 'sweep', 'sweep'])
  })
})
